const CARDS=[
["Lịch sử là gì?","Là tất cả những gì đã diễn ra trong quá khứ của con người và xã hội loài người.","baotang","kb"],
["Kể tên 3 loại tư liệu lịch sử.","Tư liệu hiện vật – tư liệu chữ viết – tư liệu truyền miệng.","khaoco"],
["Trống đồng, rìu đá thuộc loại tư liệu nào?","Tư liệu hiện vật — đồ vật còn lại đến ngày nay.","dongson","kb"],
["Học lịch sử giúp em điều gì?","Biết cội nguồn của mình, rút bài học từ quá khứ và thêm yêu quê hương, đất nước.","baotang"],
["Tư liệu truyền miệng là gì? Cho một ví dụ.","Chuyện được kể lại bằng miệng qua nhiều đời, ví dụ: truyền thuyết Sơn Tinh – Thủy Tinh.","campfire","flick"],
["1 thập kỉ, 1 thế kỉ, 1 thiên niên kỉ bằng bao nhiêu năm?","Thập kỉ = 10 năm • Thế kỉ = 100 năm • Thiên niên kỉ = 1000 năm.","sandclock"],
["Năm 2026 thuộc thế kỉ nào?","Thế kỉ XXI (21) — vì thế kỉ XXI kéo dài từ năm 2001 đến 2100.","sundial"],
["Năm 500 TCN và năm 200 TCN, năm nào đến trước (xưa hơn)?","Năm 500 TCN — số TCN càng lớn thì càng xưa.","sandclock"],
["Âm lịch và dương lịch được tính dựa vào đâu?","Âm lịch theo chuyển động của Mặt Trăng; dương lịch theo Trái Đất quay quanh Mặt Trời.","quansattroi"],
["Xếp đúng thứ tự 4 chặng tiến hóa của loài người.","Người tối cổ → Người khéo léo → Người đứng thẳng → Người tinh khôn.","skulls","strip"],
["Người tối cổ xuất hiện ở đâu, cách đây khoảng bao lâu?","Ở Đông Phi, cách đây khoảng 4 triệu năm.","evo1","kb"],
["Người khéo léo (Homo habilis) nổi bật ở điểm nào?","Biết chế tạo công cụ bằng đá — công cụ đầu tiên của loài người.","evo2"],
["Người đứng thẳng (Homo erectus) gắn với điều kì diệu nào?","Biết dùng lửa: nấu chín thức ăn, sưởi ấm, xua đuổi thú dữ.","evo3","kb"],
["Người tinh khôn (Homo sapiens) có gì khác biệt nhất?","Bộ não lớn, cơ thể gần như người ngày nay; biết mài đá, vẽ tranh trong hang.","evo4"],
["Dấu tích người tối cổ ở Việt Nam được tìm thấy ở đâu?","Ở hang Thẩm Khuyên và Thẩm Hai (Lạng Sơn) — những chiếc răng hóa thạch.","suahoathach"],
["Bầy người nguyên thủy là gì?","Nhóm vài chục người sống chung với nhau, cùng săn bắt – hái lượm để kiếm ăn.","sanbat"],
["Ở công xã thị tộc, mọi người LÀM … và HƯỞNG …?","Làm chung – hưởng chung: cùng lao động, chia đều sản phẩm, không ai giàu hơn ai.","sualamchung","kb"],
["Vì sao xã hội nguyên thủy theo chế độ mẫu hệ?","Vì phụ nữ hái lượm ổn định, lại nuôi dạy con trẻ nên là trung tâm của thị tộc.","suahailuom"],
["'Cách mạng đá mới' nghĩa là gì?","Con người biết trồng trọt, chăn nuôi và mài đá làm công cụ — không còn chỉ phụ thuộc vào săn bắt, hái lượm.","polishedaxe"],
["Người nguyên thủy thường sống ở đâu và kiếm sống bằng cách nào?","Sống trong hang động, mái đá gần sông suối; kiếm sống bằng săn bắt và hái lượm.","hangda"],
["Kim loại đầu tiên con người biết sử dụng là gì?","Là đồng — mở đầu thời đại đồ đồng.","dagger"],
["Vì sao xã hội nguyên thủy dần phân hóa giàu – nghèo?","Nhờ công cụ kim loại, sản xuất có của dư thừa; của dư rơi vào tay một số người → sinh tư hữu, giàu – nghèo.","suagiaicap"],
["Chế độ phụ hệ thay thế mẫu hệ khi nào?","Khi nam giới trở thành lực lượng chính trong sản xuất (cày bừa, chăn nuôi, rèn đúc) và giữ vai trò chủ chốt trong gia đình.","langban","kb"],
["Cuối thời nguyên thủy, xã hội chuyển biến thành xã hội gì?","Xã hội có giai cấp — nhà nước sắp ra đời.","suagiaicap"],
["Văn minh Ai Cập cổ đại hình thành bên dòng sông nào?","Sông Nin — con sông dài, hiền hòa, bồi đắp phù sa màu mỡ.","songnin"],
["Kim tự tháp được xây để làm gì? Kim tự tháp lớn nhất tên là gì?","Là lăng mộ cho các Pha-ra-ông; lớn nhất là kim tự tháp Kê-ốp.","xayktt"],
["Người Ai Cập và người Lưỡng Hà viết chữ gì?","Ai Cập: chữ tượng hình; Lưỡng Hà: chữ hình nêm (khắc trên đất sét).","suchuviet"],
["Lưỡng Hà nằm giữa hai con sông nào? Nay thuộc nước nào?","Giữa sông Ti-grơ và sông Ơ-phrát; nay là I-rắc.","map"],
["Vua Ha-mu-ra-bi nổi tiếng vì điều gì?","Ban hành bộ luật thành văn nổi tiếng, vào thế kỉ XVIII TCN.","hammurabi"],
["Văn minh Ấn Độ cổ đại hình thành bên hai sông nào?","Sông Ấn và sông Hằng.","ganges"],
["Trong xã hội Ấn Độ cổ, đẳng cấp cao nhất và thấp nhất là gì?","Cao nhất: Bà La Môn; thấp nhất: Su-đra (người lao động, phục dịch).","suadangcap"],
["Phật giáo do ai sáng lập, vào khoảng thế kỉ nào?","Do Thích Ca Mâu Ni sáng lập, vào thế kỉ VI TCN.","phatgiao"],
["Thành tựu toán học nổi tiếng nhất của Ấn Độ cổ đại là gì?","Sáng tạo ra các chữ số (mà ta dùng ngày nay) và số 0, cùng hệ đếm thập phân.","suatoanhoc"],
["Hai thành phố cổ nổi tiếng của văn minh sông Ấn tên là gì?","Mô-hen-giô Đa-rô và Ha-ráp-pa.","mohenjo"],
["Văn minh Trung Quốc cổ đại hình thành ở lưu vực sông nào?","Sông Hoàng Hà (sau mở rộng xuống lưu vực Trường Giang).","suahoangha"],
["Năm 221 TCN, Trung Quốc có sự kiện lớn nào?","Tần Thủy Hoàng thống nhất Trung Quốc, lập nhà Tần.","terracotta"],
["Vạn Lí Trường Thành được xây dựng để làm gì?","Để phòng thủ, ngăn quân du mục từ phương Bắc xâm nhập.","greatwall"],
["Chữ viết cổ nhất của Trung Quốc được khắc trên gì?","Trên giáp cốt — xương thú và mai rùa (gọi là chữ giáp cốt).","oraclebone"],
["Con đường tơ lụa nối Trung Quốc với những đâu?","Nối Trung Quốc với Trung Á và phương Tây — đường buôn bán tơ lụa, gia vị, gốm sứ.","tolua"],
["Thế vận hội Olympic bắt nguồn từ đâu, bắt đầu từ năm nào?","Từ Hy Lạp cổ đại, bắt đầu năm 776 TCN.","olympic"],
["Thành bang A-ten (Hy Lạp) nổi tiếng vì điều gì?","Vì chế độ dân chủ cổ đại — người dân được bàn bạc việc chung.","chohylap"],
["Hai bộ sử thi nổi tiếng của Hy Lạp cổ đại là gì?","I-li-át và Ô-đi-xê (của Hô-me).","suasuthi"],
["Đấu trường Cô-li-dê là công trình của nền văn minh nào?","Của La Mã cổ đại — nơi tổ chức các cuộc đấu võ, biểu diễn.","colosseum"],
["Vị thần đứng đầu trong thần thoại Hy Lạp sống ở đâu?","Thần Dớt (Zeus) — sống trên đỉnh Ô-lim-pơ.","suaolympus"],
["Vương quốc Phù Nam nằm ở khu vực nào?","Ở hạ lưu sông Mê Công — vùng phía nam Việt Nam và Campuchia ngày nay.","langdna"],
["Óc Eo là gì?","Là thương cảng (bến cảng buôn bán) sầm uất của vương quốc Phù Nam.","oceo"],
["Thánh địa Mỹ Sơn là di tích của vương quốc cổ nào?","Của vương quốc Chăm-pa ở miền Trung Việt Nam.","myson"],
["Nền văn minh đặc trưng của cư dân Đông Nam Á cổ là gì?","Văn minh lúa nước — trồng lúa ở vùng khí hậu gió mùa nóng ẩm, mưa nhiều.","sualuanuoc"],
["Vương quốc phong kiến là gì?","Nhà nước do vua đứng đầu, quan lại giúp vua cai trị. Nông dân nộp thuế và đi lao dịch, tức làm việc không công cho nhà nước.","svg48"],
["Vì sao từ thế kỉ VII, Đông Nam Á lập được vương quốc?","Vì lúa nước cho của dư nuôi quan quân, buôn bán đường biển phát triển nên cần nhà nước quản lí và bảo vệ.","svg49"],
["Sri-vi-giay-a ở đâu, giàu nhờ gì?","Ở đảo Xu-ma-tra. Giàu nhờ làm chủ eo biển Ma-lắc-ca, thu thuế tàu buôn qua lại giữa Ấn Độ và Trung Quốc.","svg50"],
["Văn hóa Ấn Độ truyền vào Đông Nam Á những gì?","Đạo Hin-đu, đạo Phật, chữ Phạn và nghệ thuật xây đền tháp.","svg51"],
["Người Đông Nam Á giữ lại gì của mình?","Tiếng nói, phong tục và cách trồng lúa nước của riêng mình.","svg52"],
["Giao lưu văn hóa là gì?","Các dân tộc gặp gỡ, trao đổi và học hỏi lẫn nhau về tôn giáo, chữ viết, nghệ thuật.","svg53"],
["Ấn Độ truyền sang Đông Nam Á những gì?","Đạo Hin-đu, đạo Phật, chữ Phạn, nghệ thuật đền tháp và truyện Ra-ma-ya-na.","svg54"],
["Người Đông Nam Á sáng tạo chữ viết riêng như thế nào?","Học chữ Phạn rồi biến đổi cho hợp tiếng nói của mình, ví dụ chữ Khmer, chữ Chăm.","svg55"],
["Bô-rô-bu-đua là gì, ở đâu?","Ngôi đền Phật giáo lớn ở đảo Java (In-đô-nê-xi-a), xây theo kiểu tháp nhiều tầng.","svg56"],
["Vì sao văn hóa Đông Nam Á vừa giống Ấn Độ vừa khác?","Vì người Đông Nam Á học văn hóa Ấn Độ nhưng vẫn giữ tiếng nói, phong tục và cách sống của mình.","svg57"],
["Nhà nước Văn Lang ra đời khi nào, ai đứng đầu?","Khoảng thế kỉ VII trước Công nguyên, Hùng Vương đứng đầu, kinh đô ở Phong Châu.","svg58"],
["Văn Lang chia thành mấy bộ, ai cai quản?","15 bộ. Lạc hầu, Lạc tướng giúp vua, Bồ chính cai quản từng bộ.","svg59"],
["Người Văn Lang sống bằng nghề gì?","Trồng lúa nước và đúc đồng, nổi tiếng nhất là trống đồng Đông Sơn.","svg60"],
["Nước Âu Lạc ra đời thế nào?","Cuối thế kỉ III trước Công nguyên, An Dương Vương hợp nhất Văn Lang với lãnh thổ của mình, đóng đô ở Cổ Loa.","svg61"],
["Thành Cổ Loa có gì đặc biệt?","Thành xây hình xoáy ốc nhiều vòng, vừa là kinh đô vừa là căn cứ phòng thủ.","svg62"],
["Chính quyền đô hộ chia nước ta thành gì?","Các quận, huyện, đặt quan người Hán sang cai trị.","svg63"],
["Đồng hóa là gì?","Bắt người Việt theo tiếng nói, chữ viết, phong tục Hán để biến Âu Lạc thành một phần của Trung Quốc.","svg64"],
["Thuế và lao dịch là gì?","Thuế nặng bắt nộp tiền và sản vật quý. Lao dịch là làm việc không công như đắp thành, đào kênh.","svg65"],
["Công cụ sắt thay đổi sản xuất ra sao?","Cày sâu hơn, ruộng mở rộng, lúa làm ra nhiều hơn trước.","svg66"],
["Người Việt giữ được gì?","Tiếng nói, phong tục, thờ cúng tổ tiên. Nhờ vậy không bị hòa tan.","svg67"],
["Hai Bà Trưng khởi nghĩa năm nào, ở đâu?","Năm 40 ở Hát Môn. Trưng Trắc lên làm vua.","svg68"],
["Bà Triệu là ai, khởi nghĩa khi nào?","Nữ anh hùng ở Phú Điền (Thanh Hóa), khởi nghĩa năm 248, muốn cưỡi gió mạnh, đạp sóng dữ.","svg69"],
["Lý Bí lập nước nào?","Năm 542 thắng lợi, lập nước Vạn Xuân, xưng Lý Nam Đế.","svg70"],
["Mai Thúc Loan và Phùng Hưng là ai?","Mai Thúc Loan (713, Mai Hắc Đế). Phùng Hưng (cuối thế kỉ VIII, Bố Cái Đại Vương).","svg71"],
["Khúc Thừa Dụ giành được gì năm 905?","Quyền tự chủ: người Việt tự cai quản đất nước mình.","svg72"],
["Bảo tồn văn hóa là gì?","Giữ gìn tiếng nói, phong tục tốt đẹp của dân tộc mình.","svg73"],
["Người Việt giữ tiếng nói bằng cách nào?","Học chữ Hán nhưng ở nhà, trong làng vẫn nói tiếng Việt.","svg74"],
["Phong tục Việt giữ được gồm gì?","Ăn trầu, nhuộm răng, thờ cúng tổ tiên.","svg75"],
["Chữ Nôm là gì?","Chữ người Việt sáng tạo từ chữ Hán để ghi âm tiếng Việt.","svg76"],
["Vì sao đồng hóa nguy hiểm?","Vì mất tiếng nói, phong tục thì dân tộc dễ bị hòa tan, không còn ý thức độc lập.","svg77"],
["Bước ngoặt đầu thế kỉ X là gì?","Ngô Quyền thắng quân Nam Hán trên sông Bạch Đằng năm 938, mở ra thời độc lập hoàn toàn.","svg78"],
["Kế đóng cọc là gì?","Đóng cọc đầu bịt sắt xuống sông, chờ thủy triều xuống để cọc đâm thủng thuyền giặc.","svg79"],
["Vì sao cọc phát huy tác dụng khi nước rút?","Lúc nước lên cọc ngập nên giặc không thấy. Nước rút cọc nhô lên đâm thuyền.","svg80"],
["Ngô Quyền làm gì năm 939?","Xưng vương, đóng đô ở Cổ Loa, khẳng định nước độc lập.","svg81"],
["Bạch Đằng 938 chấm dứt thời kì nào?","Hơn 1000 năm Bắc thuộc (từ 179 trước Công nguyên).","svg82"],
["Chăm-pa hình thành khi nào, ở đâu?","Từ thế kỉ II ở miền Trung Việt Nam, ban đầu gọi là Lâm Ấp.","svg83"],
["Kinh đô Chăm-pa ở đâu?","Đầu tiên là Trà Kiệu (Quảng Nam), sau dời về Vijaya (Bình Định).","svg84"],
["Tôn giáo chính của Chăm-pa?","Hin-đu giáo, thờ thần Si-va. Trung tâm là thánh địa Mỹ Sơn.","svg85"],
["Tháp Chăm có gì đặc biệt?","Xây bằng gạch nung xếp khít, tháp nhọn nhiều tầng.","svg86"],
["Người Chăm giỏi gì?","Đi biển, đóng thuyền và buôn bán. Sáng tạo chữ Chăm từ chữ Phạn.","svg87"],
["Phù Nam ở đâu, thịnh vượng khi nào?","Hạ lưu sông Mê Công. Thịnh vượng từ thế kỉ I đến thế kỉ VI.","svg88"],
["Óc Eo là gì?","Thương cảng sầm uất của Phù Nam, ở An Giang ngày nay.","svg89"],
["Vì sao Óc Eo sầm uất?","Nằm trên đường biển nối Ấn Độ với Trung Quốc, tàu buôn hai nước đều ghé.","svg90"],
["Người Phù Nam trị thủy bằng cách nào?","Đào kênh dẫn nước, đắp bờ giữ nước để trồng lúa và đi thuyền.","svg91"],
["Phù Nam suy yếu vì sao?","Bị Chân Lạp thôn tính và đường biển đổi hướng từ thế kỉ VI.","svg92"]
];
